# Generate a graph with 11 vertices and 23 edges
edges = []
count = 0
for u in range(11):
    for v in range(u+1, 11):
        if count < 23:
            edges.append((u, v))
            count += 1
        else:
            break
    if count >= 23:
        break

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify all edges satisfy 0 <= u < v < 11
for u, v in edges:
    assert 0 <= u < v < 11, f"Invalid edge: ({u}, {v})"

print("All edges valid!")
